    public static View hstack(View... children) {
        return new StackNode(PathlandNative.HSTACK, children);
    }

    private static final class StackNode implements View {
        private final int component;
        private final View[] children;

        StackNode(int component, View[] children) {
            this.component = component;
            this.children = children;
        }

        @Override
        public Node build() {
            Node node = new Node(0, component);
            for (View child : children) {
                node.children.add(child.build());
            }
            return node;
        }
    }
}

