+            event_slots[off..off + Opcode::SIZE].try_into().unwrap();
+        out.push(Opcode::from_bytes(&bytes));
+    }
+    header::set_u32(header, memory::OFF_EVENT_READ_CURSOR, write as u32);
+    out
+}

