        let root = renderer.borrow().root_widget();
        if let Some(root) = root {
            window.set_child(Some(&root));
        }
        window.present();

        // Idle pump: drain events (dispatch to app) then drain frames (render).
        let on_event = Rc::new(RefCell::new(on_event));
        glib::idle_add_local(move || {
            pump(&renderer, &ring, &mut |ev, r| {
                on_event.borrow_mut()(ev, r);
            });
            glib::ControlFlow::Continue
        });
    });

    app.run();
}

/// Drain the shared ring once: dispatch pending events to `on_event`, then
/// apply pending frames to the renderer.
fn pump<F>(
    renderer: &Rc<RefCell<GtkRenderer>>,
    ring: &Rc<RefCell<RingTransport>>,
    on_event: &mut F,
) where
    F: FnMut(Event, Rc<RefCell<RingTransport>>),
{
    // Events first (app may re-emit in the callback).
    let events = ring.borrow_mut().drain_events();
    for ev in events {
        on_event(ev, ring.clone());
    }

    // Frames next.
    loop {
        let batch = ring.borrow_mut().next_frame();
        match batch {
            Ok(Some(batch)) => {
                renderer.borrow_mut().apply_frame(batch.frame());
            }
            _ => break,
        }
    }
}

